window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1715be18168f0b05"]={"versions": [{"id": "FIG-1715be18168f0b05", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Methodik-Diagramm der AUTOSAR-Methodik (SPEM/UML-basiert) zur Spezifikation des methodischen Arbeitsschritts „Define Communication Matrix“ im Kontext des Systementwurfs.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Rolle: „System Engineer“ (Stereotyp bzw. Relation «performs», Multiplizität 1)</li>\n<li>Aktivität / Task: „Define Communication...“ (Aktivitätssymbol in horizontaler Flussrichtung)</li>\n<li>Eingangs-Artefakt: Topologie- bzw. Systembeschreibung (Symbolisiertes Dokumenten-Icon mit Beschriftungsanschnitt, Multiplizität 1, Relation «input»)</li>\n<li>Ausgangs-Artefakt: „Communication Matrix...“ (Symbolisiertes Dokumenten-Icon, Multiplizität 1, Relation «output»)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der „System Engineer“ führt die Aktivität „Define Communication...“ aus. Diese nimmt genau ein Eingangs-Artefakt (Topologie-/Systembeschreibung) entgegen und erzeugt als primäres Arbeitsergebnis genau eine Kommunikationsmatrix („Communication Matrix...“).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert den methodischen Teilschritt innerhalb der AUTOSAR Methodology zur Festlegung der Netzwerktopologie und Kommunikationsmatrix. Die Kardinalitäten 1:1:1 stellen sicher, dass für die Durchführung der Aktivität genau die definierte Eingangsbeschreibung vorliegen muss und die Kommunikationsmatrix als verbindliches Folgeartefakt hervorgeht.</p>"}, {"id": "FIG-ecc3d7c0b6f6d14b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Methodik-Diagramm der AUTOSAR-Methodik (SPEM/UML-basiert) zur Spezifikation des methodischen Arbeitsschritts „Define Communication Matrix“ im Kontext des Systementwurfs.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Rolle: „System Engineer“ (Stereotyp bzw. Relation «performs», Multiplizität 1)</li>\n<li>Aktivität / Task: „Define Communication...“ (Aktivitätssymbol in horizontaler Flussrichtung)</li>\n<li>Eingangs-Artefakt: Topologie- bzw. Systembeschreibung (Symbolisiertes Dokumenten-Icon mit Beschriftungsanschnitt, Multiplizität 1, Relation «input»)</li>\n<li>Ausgangs-Artefakt: „Communication Matrix...“ (Symbolisiertes Dokumenten-Icon, Multiplizität 1, Relation «output»)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der „System Engineer“ führt die Aktivität „Define Communication...“ aus. Diese nimmt genau ein Eingangs-Artefakt (Topologie-/Systembeschreibung) entgegen und erzeugt als primäres Arbeitsergebnis genau eine Kommunikationsmatrix („Communication Matrix...“).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert den methodischen Teilschritt innerhalb der AUTOSAR Methodology zur Festlegung der Netzwerktopologie und Kommunikationsmatrix. Die Kardinalitäten 1:1:1 stellen sicher, dass für die Durchführung der Aktivität genau die definierte Eingangsbeschreibung vorliegen muss und die Kommunikationsmatrix als verbindliches Folgeartefakt hervorgeht.</p>"}], "trans": [{"from": "FIG-1715be18168f0b05", "to": "FIG-ecc3d7c0b6f6d14b", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
